<template><view class="page"><view class="eyebrow">学习档案</view><view class="page-title">我的申论</view><view class="profile-card card"><view class="profile-avatar">{{ initial }}</view><view><view class="card-title">{{ user?.nickname || user?.username || '学习者' }}</view><view class="card-desc">{{ user?.username || '正在加载账号' }}</view></view><view class="profile-points">{{ user?.points || 0 }} 积分</view></view><view class="section-head"><view class="section-title">学习资产</view></view><view v-for="item in items" :key="item.label" class="card row" @tap="openItem(item.key)"><view class="card-title">{{ item.label }}</view><view class="tag">{{ item.enabled ? '查看' : '规划中' }}</view></view><view class="logout" @tap="logout">退出登录</view></view></template>
<script setup lang="ts">import { computed, ref } from 'vue'; import Taro, { useDidShow } from '@tarojs/taro'; import { api, type UserMe } from '@/api'; import { clearToken, isLoggedIn } from '@/utils/auth'; import { showConfirm, showToast } from '@/utils/platform'; const user=ref<UserMe|null>(null); const initial=computed(()=>String(user.value?.nickname||user.value?.username||'知').slice(0,1)); const items=[{key:'mines',label:'我的批注与开采',enabled:true},{key:'terms',label:'收藏的表达',enabled:true},{key:'drills',label:'训练与批改记录',enabled:true},{key:'settings',label:'学习计划与设置',enabled:false}]; async function load(){if(!isLoggedIn())return Taro.navigateTo({url:'/pages/auth/login'});const response=await api.getMe();if(response.code===0&&response.data)user.value=response.data;else showToast(response.message||'账号信息加载失败')}function openItem(key:string){if(key==='drills')Taro.switchTab({url:'/pages/training/index'});else if(key==='mines')Taro.navigateTo({url:'/pages/reading/mines'});else if(key==='terms')Taro.navigateTo({url:'/pages/reading/terms'});else showToast('该功能正在规划中')} async function logout(){if(!await showConfirm('退出当前账号？'))return;clearToken();user.value=null;Taro.navigateTo({url:'/pages/auth/login'})} useDidShow(()=>void load())</script>
